import re
import shutil
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("dns-zone-archive")

ACTIVE_ZONES_DIRECTORY = Path("/etc/bind/zones")
ARCHIVED_ZONES_DIRECTORY = Path("/var/backups/dns/archived")


@mcp.tool()
def archive_zone_file(zone_name: str, archive_subfolder: str = "") -> dict:
    normalized_zone_name = zone_name.strip().lower().rstrip(".")
    source_zone_file_path = ACTIVE_ZONES_DIRECTORY / f"db.{normalized_zone_name}"

    if not source_zone_file_path.is_file():
        return {"archived": False, "error": f"No zone file for {normalized_zone_name}"}

    zone_file_text_content = source_zone_file_path.read_text()
    soa_serial_match_result = re.search(
        r"SOA\s+\S+\s+\S+\s*\(?\s*(\d+)", zone_file_text_content, re.IGNORECASE
    )
    discovered_soa_serial_number = (
        int(soa_serial_match_result.group(1)) if soa_serial_match_result else None
    )
    total_record_line_count = sum(
        1
        for each_line in zone_file_text_content.splitlines()
        if each_line.strip() and not each_line.strip().startswith(";")
    )

    destination_archive_directory = ARCHIVED_ZONES_DIRECTORY
    if archive_subfolder:
        destination_archive_directory = ARCHIVED_ZONES_DIRECTORY / archive_subfolder
    destination_archive_directory.mkdir(parents=True, exist_ok=True)

    destination_zone_file_path = destination_archive_directory / source_zone_file_path.name
    final_location = shutil.move(str(source_zone_file_path), str(destination_zone_file_path))

    return {
        "archived": True,
        "zone": normalized_zone_name,
        "soa_serial": discovered_soa_serial_number,
        "record_lines": total_record_line_count,
        "new_location": final_location,
    }

import sqlite3

from agents import function_tool

DB_PATH = "/var/lib/dns/records.db"
ALLOWED_TYPES = {"A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "CAA"}


@function_tool
def add_dns_record(zone: str, name: str, record_type: str, value: str, ttl: int = 3600) -> dict:
    record_type = record_type.upper()
    if record_type not in ALLOWED_TYPES:
        return {"created": False, "error": f"Unsupported record type {record_type}"}
    conn = sqlite3.connect(DB_PATH)
    try:
        cursor = conn.execute(
            "INSERT INTO records (zone, name, type, value, ttl) VALUES (?, ?, ?, ?, ?)",
            (zone, name, record_type, value, ttl),
        )
        conn.commit()
        record_id = cursor.lastrowid
    finally:
        conn.close()
    return {
        "created": True,
        "id": record_id,
        "zone": zone,
        "name": name,
        "type": record_type,
        "value": value,
        "ttl": ttl,
    }
